// A trip owns this state. No score, fare, route or vehicle mutations occur here.
[Serializable] public sealed class PassengerBehaviorState {
 // Preset identity is separate from the existing action module Type. Absent fields mean legacy state.
 public string PresetId,PresetName,PresetIntro;
 public string[] PresetTraits;
 public PassengerOverride[] PresetOverrides;
 [NonSerialized] PassengerContent cachedContent;
 public PassengerContent Content {get{return cachedContent??(cachedContent=new PassengerContent(PresetOverrides));}}
 public PassengerType PresetPool,PresetRepresentative;
 public bool PresetQuiet;
 public PassengerType Pool {get{return string.IsNullOrEmpty(PresetId)?Type:PresetPool;}}
 public PassengerType RepresentativeType {get{return string.IsNullOrEmpty(PresetId)?Type:PresetRepresentative;}}
 public int RepresentativeVariant {get{return RepresentativeType==Type?Variant:(int)(DrunkRideState.Hash(Identity+":variant")%3u);}}
 public bool HasTrait(string id){return PresetTraits!=null&&Array.IndexOf(PresetTraits,id)>=0;}
 public bool HasSleep {get{return Type==PassengerType.Sleeping||HasTrait("body.sleepy");}}
 public bool IsDrunk {get{return string.IsNullOrEmpty(PresetId)?Type==PassengerType.Drunk:Array.IndexOf(PresetTraits,"body.drunk")>=0;}}
 public static PassengerBehaviorState CreateConfigured(string identity,PassengerType pool,PassengerType[] eligible,string selectionSeed){
  string json=ContentTuning.Text("passenger.presets","");if(json.Length==0)return Create(identity,pool);
  var all=PassengerPresetCatalog.Parse(json);int total=0;foreach(var p in all)if(p.pool==pool.ToString()&&p.enabled&&p.weight>0)total+=p.weight;
  if(total==0)return Create(identity,PassengerType.General);
  int pick=(int)(DrunkRideState.Hash((selectionSeed??identity)+":passenger-preset:"+pool)%(uint)total);
  foreach(var p in all){if(p.pool!=pool.ToString()||!p.enabled||p.weight<=0)continue;pick-=p.weight;if(pick>=0)continue;
   var representative=(PassengerType)Enum.Parse(typeof(PassengerType),p.RepresentativeModule);
   // Never replace an unavailable module with another random preset on a different route.
   if(representative!=PassengerType.General&&eligible!=null&&Array.IndexOf(eligible,representative)<0)return Create(identity,PassengerType.General);
   var result=Create(identity,(PassengerType)Enum.Parse(typeof(PassengerType),p.ActionModule));result.PresetOverrides=PassengerContent.Clone(p.overrides);result.SpillPlanned=DrunkRideState.Hash(identity+":food-spill")%100<result.Content.Int("effect.food.spillPercent",25);result.PresetId=p.id;result.PresetName=p.name;result.PresetIntro=p.intro;result.PresetPool=pool;result.PresetTraits=(string[])p.traits.Clone();result.PresetRepresentative=representative;result.PresetQuiet=p.Has("speech.quiet");result.Quiet|=result.PresetQuiet;result.InitializeTraits();return result;
  }return Create(identity,PassengerType.General);
 }
 public int TraitVersion;
 public bool TraitsInitialized,NauseaPlanned,NauseaIncident,NauseaDirtOccurred,UmbrellaDirtOccurred,TemperatureCorrectionShown,TemperatureCorrectionPending;
 public int NauseaChoice=-1,UmbrellaChoice=-1,TemperatureSetting=-1,TemperaturePreference,TemperatureResponseCount;
 public float NauseaLevel,NauseaRestRemaining,UmbrellaPrepareRemaining,TemperatureComfortElapsed,TemperatureDiscomfortElapsed;
 public string LastTraitEffect;
 public float TraitWorkRemaining {get{return NauseaRestRemaining+UmbrellaPrepareRemaining;}}
 public int TraitSatisfactionDelta {get{return !HasTrait("body.temperatureSensitive")||!Boarded?0:TemperatureSetting==TemperaturePreference&&TemperatureComfortElapsed>=Content.Number("effect.temperature.comfortSeconds",15)?Content.Int("effect.temperature.matchSatisfaction",3):TemperatureDiscomfortElapsed>=Content.Number("effect.temperature.discomfortSeconds",20)?Content.Int("effect.temperature.mismatchSatisfaction",-2):0;}}
 public string TraitStatus {get{return (HasTrait("body.nausea")?"메스꺼움 "+Math.Round(NauseaLevel)+" · "+(NauseaIncident?(NauseaDirtOccurred?"오염 발생":"봉투로 오염 예방"):NauseaChoice==1?"봉투 준비":"상태 관찰"):"")+(HasTrait("body.temperatureSensitive")?"  차내 온도 "+(TemperatureSetting==0?"따뜻하게":TemperatureSetting==1?"시원하게":"기존 유지")+" · 쾌적 만족도 "+TraitSatisfactionDelta:"")+(HasTrait("item.wetUmbrella")?"  우산 "+(UmbrellaChoice==0?"감싸기":UmbrellaChoice==1?"그대로 보관":"응대 전"):"");}}
 public void InitializeTraits(){if(TraitsInitialized)return;TraitVersion=1;TraitsInitialized=true;TemperaturePreference=(int)(DrunkRideState.Hash(Identity+":temperature")%2u);NauseaPlanned=HasTrait("body.nausea")&&DrunkRideState.Hash(Identity+":nausea")%100<Content.Int("effect.nausea.eventPercent",100);}
 public string TraitAction {get{if(Arrived||Settled||Sleeping||FollowupPending)return "";if(HasTrait("item.wetUmbrella")&&UmbrellaChoice<0)return "umbrella";if(Type!=PassengerType.General&&Choice<0)return "";if(!Boarded)return "";if(HasTrait("body.temperatureSensitive")&&(TemperatureSetting<0||TemperatureCorrectionPending))return "temperature";if(HasTrait("body.nausea")&&NauseaPlanned&&!NauseaIncident&&NauseaChoice<0&&NauseaLevel>=Content.Number("effect.nausea.warning",20))return "nausea";return "";}}
 string TraitPrompt {get{string a=TraitAction;if(a=="umbrella")return Content.Text("trait.umbrella.prompt","우산이 젖었어요. 어떻게 보관할까요?");if(a=="nausea")return Content.Text("trait.nausea.prompt","속이 울렁거려요. 안전한 곳에서 도와주실 수 있나요?");return Content.Text(TemperatureCorrectionPending?"trait.temperature.correction":"trait.temperature.prompt",TemperatureCorrectionPending?"차내 온도가 아직 불편해요. 다시 맞춰 주실 수 있나요?":"차내 온도를 조금 맞춰 주실 수 있나요?")+" · "+(TemperaturePreference==0?"따뜻하게 부탁해요.":"시원하게 부탁해요.");}}
 string[] TraitChoiceLabels {get{string a=TraitAction;string[] rows=a=="umbrella"?new[]{"우산을 감싸서 보관할게요","그대로 보관해 주세요"}:a=="nausea"?new[]{"안전 정차 후 잠시 쉬어 갈게요","봉투를 준비해 드릴게요"}:new[]{"차내를 따뜻하게 맞출게요","차내를 시원하게 맞출게요","현재 온도를 유지할게요"};for(int i=0;i<rows.Length;i++)rows[i]=Content.Text("trait."+a+".choice."+i,rows[i]);return rows;}}
 string[] TraitChoiceEffects {get{if(TraitAction=="umbrella")return new[]{"안전 정차 준비 "+Content.Number("effect.umbrella.prepareSeconds",6)+"초 · 우산 오염 예방","실제 탑승 시 청결 -"+Content.Int("effect.umbrella.dirt",3)+" · 1회"};if(TraitAction=="nausea")return new[]{"안전 정차 휴식 "+Content.Number("effect.nausea.restSeconds",8)+"초 후 메스꺼움 -"+Content.Number("effect.nausea.relief",35),"앞으로 발생할 사건의 오염 예방 · 이미 발생한 오염 유지"};string evaluation=" · 희망 온도 "+Content.Number("effect.temperature.comfortSeconds",15)+"초 유지 시 만족도 +"+Content.Int("effect.temperature.matchSatisfaction",3)+" / 불편 "+Content.Number("effect.temperature.discomfortSeconds",20)+"초 시 "+Content.Int("effect.temperature.mismatchSatisfaction",-2)+" · 누적 가산 없음";return new[]{"차내 따뜻하게"+evaluation,"차내 시원하게"+evaluation,"차내 기존 유지"+evaluation};}}
 string TraitWorkDialogue {get{return (UmbrellaPrepareRemaining>0?"우산을 감싸고 있어요.":"안전하게 정차해 속을 가라앉히고 있어요.")+" "+Math.Ceiling(TraitWorkRemaining)+"초";}}
 bool RespondTrait(int choice){InitializeTraits();string a=TraitAction;LastTraitEffect=TraitChoiceEffects[choice];if(a=="umbrella"){UmbrellaChoice=choice;UmbrellaPrepareRemaining=choice==0?(float)Content.Number("effect.umbrella.prepareSeconds",6):0;if(Boarded&&choice==1)UmbrellaDirtOccurred=true;}else if(a=="nausea"){NauseaChoice=choice;NauseaRestRemaining=choice==0?(float)Content.Number("effect.nausea.restSeconds",8):0;if(choice==0&&NauseaRestRemaining==0)NauseaLevel=Math.Max(0,NauseaLevel-(float)Content.Number("effect.nausea.relief",35));}else{TemperatureSetting=choice;TemperatureResponseCount++;TemperatureCorrectionPending=false;TemperatureComfortElapsed=0;}return true;}
 bool AdvanceTraits(float seconds,bool safe,bool moving){bool changed=false;if(safe&&!moving){if(UmbrellaPrepareRemaining>0){UmbrellaPrepareRemaining=Math.Max(0,UmbrellaPrepareRemaining-seconds);changed|=UmbrellaPrepareRemaining==0;}if(NauseaRestRemaining>0){NauseaRestRemaining=Math.Max(0,NauseaRestRemaining-seconds);if(NauseaRestRemaining==0){NauseaLevel=Math.Max(0,NauseaLevel-(float)Content.Number("effect.nausea.relief",35));changed=true;}}}if(!Boarded||Arrived)return changed;InitializeTraits();string previous=TraitAction;int delta=TraitSatisfactionDelta;if(HasTrait("body.nausea")&&NauseaPlanned&&!NauseaIncident&&moving){NauseaLevel=Math.Min(100,NauseaLevel+seconds*(float)Content.Number("effect.nausea.rate",.35));changed|=CheckNauseaIncident();}if(HasTrait("body.temperatureSensitive")){if(TemperatureSetting==TemperaturePreference)TemperatureComfortElapsed=Math.Min((float)Content.Number("effect.temperature.comfortSeconds",15),TemperatureComfortElapsed+seconds);else {TemperatureDiscomfortElapsed=Math.Min((float)Content.Number("effect.temperature.discomfortSeconds",20),TemperatureDiscomfortElapsed+seconds);if(TemperatureSetting>=0&&!TemperatureCorrectionShown&&TemperatureDiscomfortElapsed>=Content.Number("effect.temperature.discomfortSeconds",20)){TemperatureCorrectionShown=TemperatureCorrectionPending=true;changed=true;}}}return changed||previous!=TraitAction||delta!=TraitSatisfactionDelta;}
 bool CheckNauseaIncident(){if(NauseaIncident||!NauseaPlanned||NauseaLevel<Content.Number("effect.nausea.threshold",70))return false;NauseaIncident=true;NauseaDirtOccurred=NauseaChoice!=1;return true;}
 public bool ObserveNauseaJolt(){if(!Boarded||Arrived||Settled||!HasTrait("body.nausea")||!NauseaPlanned||NauseaIncident)return false;NauseaLevel=Math.Min(100,NauseaLevel+(float)Content.Number("effect.nausea.jolt",12));CheckNauseaIncident();return true;}
 void ValidateTraits(){
  if(TraitVersion==0){if(HasTrait("body.nausea")||HasTrait("body.temperatureSensitive")||HasTrait("item.wetUmbrella")||TraitsInitialized||NauseaPlanned||NauseaIncident||NauseaDirtOccurred||UmbrellaDirtOccurred||TemperatureCorrectionShown||TemperatureCorrectionPending||NauseaLevel!=0||NauseaRestRemaining!=0||UmbrellaPrepareRemaining!=0||TemperatureComfortElapsed!=0||TemperatureDiscomfortElapsed!=0||TemperatureResponseCount!=0||TemperaturePreference!=0||NauseaChoice>0||NauseaChoice< -1||UmbrellaChoice>0||UmbrellaChoice< -1||TemperatureSetting>0||TemperatureSetting< -1||!string.IsNullOrEmpty(LastTraitEffect))throw new ArgumentException("Hidden trait state in legacy snapshot");NauseaChoice=UmbrellaChoice=TemperatureSetting=-1;return;}
  if(TraitVersion!=1)throw new ArgumentException("Unknown trait state version");
  if(NauseaChoice>=0&&(!Boarded||!NauseaPlanned)||NauseaIncident&&NauseaDirtOccurred!=(NauseaChoice!=1)||Boarded&&HasTrait("item.wetUmbrella")&&(UmbrellaChoice<0||UmbrellaChoice==1&&!UmbrellaDirtOccurred)||!TraitsInitialized&&(NauseaChoice>=0||NauseaLevel>0||NauseaIncident||TemperatureSetting>=0||TemperatureComfortElapsed>0||TemperatureDiscomfortElapsed>0))throw new ArgumentException("Impossible trait event history");
  foreach(float value in new[]{NauseaLevel,NauseaRestRemaining,UmbrellaPrepareRemaining,TemperatureComfortElapsed,TemperatureDiscomfortElapsed})if(float.IsNaN(value)||float.IsInfinity(value)||value<0)throw new ArgumentException("Invalid trait timing");
  if(NauseaChoice< -1||NauseaChoice>1||UmbrellaChoice< -1||UmbrellaChoice>1||TemperatureSetting< -1||TemperatureSetting>2||TemperaturePreference<0||TemperaturePreference>1||TemperatureResponseCount<0||TemperatureResponseCount>2||LastTraitEffect!=null&&LastTraitEffect.Length>2000)throw new ArgumentException("Invalid trait response");
  if(NauseaLevel>100||NauseaRestRemaining>Content.Number("effect.nausea.restSeconds",8)||UmbrellaPrepareRemaining>Content.Number("effect.umbrella.prepareSeconds",6)||TemperatureComfortElapsed>Content.Number("effect.temperature.comfortSeconds",15)||TemperatureDiscomfortElapsed>Content.Number("effect.temperature.discomfortSeconds",20))throw new ArgumentException("Trait timer exceeds contract");
  if(!HasTrait("body.nausea")&&(NauseaPlanned||NauseaIncident||NauseaDirtOccurred||NauseaChoice>=0||NauseaLevel>0||NauseaRestRemaining>0)||NauseaIncident&&(!NauseaPlanned||!Boarded)||NauseaDirtOccurred&&(!NauseaIncident||NauseaChoice==1)||NauseaRestRemaining>0&&NauseaChoice!=0||!HasTrait("item.wetUmbrella")&&(UmbrellaChoice>=0||UmbrellaDirtOccurred||UmbrellaPrepareRemaining>0)||UmbrellaDirtOccurred&&(!Boarded||UmbrellaChoice!=1)||UmbrellaPrepareRemaining>0&&UmbrellaChoice!=0)throw new ArgumentException("Inconsistent trait event");
  if(!HasTrait("body.temperatureSensitive")&&(TemperatureSetting>=0||TemperatureComfortElapsed>0||TemperatureDiscomfortElapsed>0||TemperatureCorrectionShown||TemperatureCorrectionPending||TemperatureResponseCount>0)||TemperatureSetting>=0&&(!Boarded||TemperatureResponseCount==0)||TemperatureSetting<0&&TemperatureResponseCount!=0||TemperatureCorrectionPending&&(!TemperatureCorrectionShown||TemperatureResponseCount!=1)||TemperatureCorrectionShown&&TemperatureDiscomfortElapsed<Content.Number("effect.temperature.discomfortSeconds",20)||Settled&&TraitWorkRemaining>0)throw new ArgumentException("Inconsistent cabin comfort");
 }

