 public bool SetRepresentativeContext(PassengerRepresentativeStatus status,string response){if(!Enum.IsDefined(typeof(PassengerRepresentativeStatus),status))throw new ArgumentException("Unknown representative status");response=response??"";if(response.Length>240)response=response.Substring(0,240);if(RepresentativeStatus==status&&RepresentativeResponse==response)return false;RepresentativeStatus=status;RepresentativeResponse=response;return true;}
 bool UsesRepresentative {get{return RepresentativeType==PassengerType.Comfort||RepresentativeType==PassengerType.Hurried||RepresentativeType==PassengerType.RouteChecking||RepresentativeType==PassengerType.Errand||RepresentativeType==PassengerType.PrecisionStop;}}
 string RepresentativeTopic {get{return RepresentativeType==PassengerType.Comfort?"승차감":RepresentativeType==PassengerType.Hurried?(Variant==0?"도착 예상":"약속 시간"):RepresentativeType==PassengerType.Errand?"경유":RepresentativeType==PassengerType.PrecisionStop?"안전 하차":"경로";}}
 // Dialogue and CompletionReaction are spoken by the passenger; the saved response belongs to the driver.
 string RepresentativeReaction {get{string topic=RepresentativeTopic;switch(RepresentativeStatus){case PassengerRepresentativeStatus.Accepted:return topic+" 안내를 확인했어요. 고마워요.";case PassengerRepresentativeStatus.Deferred:return topic+" 요청을 안전상 보류하신다는 말씀 이해했어요.";case PassengerRepresentativeStatus.Succeeded:return topic+" 약속을 이행해 주셔서 고마워요.";case PassengerRepresentativeStatus.Failed:return topic+" 약속은 아쉽네요. 다음에는 부탁드려요.";case PassengerRepresentativeStatus.Neutral:return topic+"에 대해 안내해 주셔서 고마워요.";case PassengerRepresentativeStatus.Pending:return topic+"에 대해서는 답을 듣지 못했으니 별도 약속으로 생각하지 않을게요.";default:return Arrived||Settled?"안전하게 데려다주셔서 고마워요.":"따로 부탁드린 건 없어요. 안전하게 부탁해요.";}}}

