 static readonly string[][] intros={new[]{"안녕하세요. 목적지까지 부탁해요.","창밖을 보며 갈게요.","반갑습니다. 출발할까요?"},new[]{"오늘 이야기가 자꾸 나오네요.","조금 취했네요. 폐를 끼치면 미안해요.","조용히 집까지 부탁해요."},new[]{"잠깐 눈 붙일게요. 도착하면 깨워 주세요.","오늘 하루가 길었어요… 졸리네요.","잠깐 잘게요. 중간에 위치를 물어볼 수도 있어요.","깊이 잠들면 도착해서 한 번 더 불러 주세요."},new[]{"부드럽게 운전해 주실 수 있나요?","차가 흔들리면 힘들어요.","편안하게 갈 수 있을까요?"},new[]{"도착 예상 시간을 알고 싶어요.","중간에 시간을 다시 확인할게요.","신호가 길어 보여도 안전하게 부탁해요."},new[]{"큰길로 가는 이유가 궁금해요.","짧은 길도 가능한가요?","제가 알던 길과 다른가 봐요."},new[]{"중간에 들를 곳을 먼저 확인하고 싶어요.","가능한 경유지가 있으면 알려 주세요.","용무 후 원래 목적지로 가는 거죠?"},new[]{"큰 가방을 싣고 내려야 해요.","상자를 여러 개 실어야 해요.","짐이 흔들리지 않게 싣고 싶어요."},new[]{"가방 밑에 흙이 묻었어요.","화분 받침에 흙이 남았네요.","밖에서 쓰던 짐이라 바닥이 더러워요."},new[]{"간식을 먹어도 될까요?","음료와 간식을 먹어도 될까요?","도시락을 먹어도 될까요?"},new[]{"입구 가까운 안전한 장소가 있나요?","내린 뒤 걸어갈 길을 확인하고 싶어요.","안전한 하차 지점인지 확인할게요."},new[]{"잠깐 제 이야기를 해도 될까요?","이 동네 이야기가 궁금해요.","앞서 물었던 걸 다시 확인해도 될까요?"}};
 public static PassengerBehaviorState Create(string identity,PassengerType type){if(string.IsNullOrEmpty(identity)||!Enum.IsDefined(typeof(PassengerType),type))throw new ArgumentException("Invalid passenger identity/type");int variant=(int)(DrunkRideState.Hash(identity+":variant")%(type==PassengerType.Sleeping?4u:3u));return new PassengerBehaviorState{TraitVersion=1,FoodSpillTimingVersion=1,Identity=identity,Type=type,Variant=variant,Quiet=type==PassengerType.Drunk&&variant==2,SpillPlanned=DrunkRideState.Hash(identity+":food-spill")%100<ContentTuning.Int("effect.food.spillPercent",25)};}
 public string TypeLabel {get{return string.IsNullOrEmpty(PresetId)?labels[(int)Type]:PresetName;}}
 public string VariantLabel {get{return variants[(int)Type][Variant];}}
 public bool HasChoice {get{return !Arrived&&!Settled&&!Sleeping&&((Type!=PassengerType.General&&(Choice<0||FollowupPending))||TraitAction.Length>0);}}
 public bool BoardingReady {get{return !Settled&&TraitWorkRemaining<=0&&(!HasTrait("item.wetUmbrella")||UmbrellaChoice>=0)&&PreparationRemaining<=0&&((Type!=PassengerType.Luggage&&Type!=PassengerType.MuddyLuggage)||Choice>=0);}}
 public bool UnloadReady {get{return UnloadRemaining<=0&&PreparationRemaining<=0&&TraitWorkRemaining<=0;}}
 public float WorkRemaining {get{return PreparationRemaining+UnloadRemaining+TraitWorkRemaining;}}
 public static int FoodPermissionSatisfaction {get{return ContentTuning.Int("effect.food.satisfaction",5);}}
 public int SatisfactionDelta {get{return Type==PassengerType.Food&&Boarded&&Choice==1?FoodPermissionSatisfaction:0;}}
 public string[] ChoiceLabels {get{if(TraitAction.Length>0)return TraitChoiceLabels;var rows=RawChoiceLabels;if(FollowupPending)return rows;for(int i=0;i<rows.Length;i++)rows[i]=Content.Text("type."+Type+".choice."+i,rows[i]);return rows;}}
 // NPC acknowledgement of the selected action; never reuse an edited driver option as speech.
 public string ReactionForChoice(int choice){
